import { readFileSync, writeFileSync } from "node:fs";

const CONTRACTS = ["RootRegistry", "ComplianceRegistry", "Settlement"] as const;
const out = new URL("../src/abi.ts", import.meta.url);
const artifacts = new URL("../../contracts/out/", import.meta.url);

const lower = (name: string) => `${name[0]?.toLowerCase()}${name.slice(1)}`;

const render = () =>
  `${[
    "// Generated by scripts/export-abis.ts from the compiled contracts. Do not edit.",
    ...CONTRACTS.map((name) => {
      const { abi } = JSON.parse(
        readFileSync(new URL(`${name}.sol/${name}.json`, artifacts), "utf8"),
      );
      return `export const ${lower(name)}Abi = ${JSON.stringify(abi, null, 2)} as const;`;
    }),
  ].join("\n\n")}\n`;

const source = render();
if (process.argv.includes("--check")) {
  if (readFileSync(out, "utf8") !== source) {
    console.error("src/abi.ts is out of date: run `pnpm --filter @keelson/sdk export:abis`");
    process.exit(1);
  }
} else {
  writeFileSync(out, source);
}
